class Editor {
  private content: string = '';
  private cursor: number = 0;
  saveSnapshot() { return { content: this.content, cursor: this.cursor }; }
  restoreSnapshot(s: { content: string; cursor: number }) { this.content = s.content; this.cursor = s.cursor; }
}
class History {
  private snapshots: any[] = [];
  push(s: any) { this.snapshots.push(s); }
  pop() { return this.snapshots.pop(); }
}

// Version A
class SnapshotToken {
  private state: string;
  constructor(s: string) { this.state = s; }
  // Only originator should access the internal state
}
class EditorV1 {
  private content = '';
  save(): SnapshotToken { return new SnapshotToken(this.content); }
  restore(t: SnapshotToken) { /* originator extracts state internally */ }
}

// Version B
class EditorV2 {
  private content = '';
  save() { return { content: this.content }; }
  restore(s: { content: string }) { this.content = s.content; }
}
class History { items: any[] = []; push(s: any) { this.items.push(s); } pop() { return this.items.pop(); } }
